    write(DOCS/'image.html',shell('The source image',f'''<section><p class="eyebrow">ARTIFACT 01 / MARKETING STUDIO IMAGE</p><h1>The globe before motion.</h1><p class="lede">The original PNG used as the starting-image input for the video. Requested 2K / 3:2; measured 2048 × 1360.</p><figure class="standalone"><a href="assets/globe.png"><img src="assets/globe.png" alt="Rainy fishing village inside a cracked glass globe on a kitchen table" width="2048" height="1360"></a><figcaption>Original generated image, published without resizing or re-encoding.</figcaption></figure><div class="actions"><a class="button" href="video.html">Watch its video</a><a class="button secondary" href="assets/globe.png" download>Download PNG</a><a href="index.html#prompts">Prompt and request</a></div></section>'''))
    write(DOCS/'video.html',shell('The generated video',f'''<section><p class="eyebrow">ARTIFACT 02 / SEEDANCE 2.0</p><h1>Ten seconds inside the globe.</h1><p class="lede">Generated from the source globe image and the motion prompt. Requested 10 seconds / 720p; measured 10.08 seconds / 1112 × 834.</p><figure class="standalone"><video controls playsinline preload="metadata" poster="assets/video-first-frame.jpg" aria-label="Generated globe animation"><source src="assets/globe.mp4" type="video/mp4">Your browser cannot play this video. <a href="assets/globe.mp4">Open the MP4</a>.</video><figcaption>Use Play and the volume control. This is the completed output, with H.264 video and an AAC audio stream. Playback does not submit a new generation.</figcaption></figure><div class="actions"><a class="button" href="assets/globe.mp4" download>Download MP4</a><a class="button secondary" href="image.html">View the source image</a><a href="index.html#evidence">What changed?</a></div><p class="note">The service changed the source proportions to 4:3. The correct image was supplied; a pixel-identical first frame and perfect camera lock have not been certified.</p></section>'''))
